def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    last_my = me[-1]
    last_op = op[-1]

    opp_c = 0
    my_c = 0
    for i in range(n):
        if op[i] == 'C':
            opp_c += 1
        if me[i] == 'C':
            my_c += 1

    opp_rate = opp_c / n
    opp_d = n - opp_c
    my_d = n - my_c

    w = 6 if n >= 6 else n
    rec_opp_c = 0
    for i in range(n - w, n):
        if op[i] == 'C':
            rec_opp_c += 1

    opp_d_run = 0
    for x in reversed(op):
        if x == 'D':
            opp_d_run += 1
        else:
            break

    recent_my_d = 0
    start = n - 3
    if start < 0:
        start = 0
    for i in range(start, n):
        if me[i] == 'D':
            recent_my_d += 1

    if opp_rate < 0.25:
        if last_op == 'C' and rec_opp_c >= max(2, w - 2):
            return 'C'
        return 'D'

    if last_op == 'D':
        if last_my == 'D':
            if opp_rate < 0.35 and opp_d_run >= 3:
                return 'D'
            if rec_opp_c == 0 and opp_d_run >= 4:
                return 'D'
            return 'C'

        if n >= 2 and me[-2] == 'C' and op[-2] == 'D':
            return 'D'
        if opp_d_run >= 3:
            return 'D'
        if opp_rate < 0.35:
            return 'D'
        if recent_my_d > 0:
            return 'C'
        return 'D'

    if last_my == 'D':
        return 'D'

    if my_d == 0 and opp_d == 0 and n == 10:
        return 'D'
    return 'C'
